<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {createReadGate,errorText} from './client.mjs';import {dimensions,lockText} from './media.mjs';
const props=defineProps({policy:Object,category:String,client:Object,status:Object,schedule:Object});const result=ref(null),error=ref(''),busy=ref(false),gate=createReadGate();let timer;
async function load(){if(!props.category||!props.policy.bindings[props.category])return;const read=gate.begin();busy.value=true;error.value='';result.value=null;try{const r=await props.client.post('/configuration/policy-summary',{config_revision:props.status.current.value.revision,runtime_generation:props.status.health.value.generation,policy:props.policy,category_id:props.category});if(read.current())result.value=r.result}catch(e){if(read.current())error.value=errorText(e)}finally{if(read.current())busy.value=false}}
watch(()=>JSON.stringify([props.policy,props.category,props.status.current.value?.revision]),()=>{gate.begin();result.value=null;clearTimeout(timer);timer=setTimeout(load,250)},{immediate:true});onBeforeUnmount(()=>{clearTimeout(timer);gate.close()});
</script>
<template><section class="sb-policy-reference"><p v-if="busy" role="status">正在读取当前草稿的完整策略…</p><p v-if="error" role="alert">策略摘要暂时无法加载。<VBtn variant="text" @click="load">重新加载</VBtn></p><template v-if="result"><p>允许 {{result.summary.resolutions.map(r=>r===2160?'4K':r+'p').join('、')}}；按 {{result.summary.comparison.map(r=>dimensions[r.dimension]).join(' › ')}} 依次比较。</p><details><summary>查看完整规则</summary><p>{{result.summary.group}} · {{result.summary.source}}</p><ol class="sb-rank-rules"><li v-for="r in result.summary.comparison" :key="r.dimension"><strong>{{dimensions[r.dimension]}}</strong><span>{{r.order.join(' › ')}}<small v-if="r.note">{{r.note}}</small></span></li></ol><details v-if="result.summary.rule_details?.length"><summary>发布组与片源的具体条件</summary><dl class="sb-rule-explanations"><template v-for="r in result.summary.rule_details" :key="r.name"><dt>{{r.name}}</dt><dd>{{r.explanation}}</dd></template></dl></details><h4>锁定条件</h4><p v-if="!Object.keys(result.locks).length">没有额外锁定。</p><p v-for="(v,k) in result.locks" :key="k">{{dimensions[k]||({platform:'平台',group:'发布组',season:'季'})[k]||k}}：{{lockText(k,v)}}</p><details v-if="result.custom_rules.length||result.custom_admission"><summary>自定义准入条件</summary><p v-for="r in result.custom_rules" :key="r.name" class="sb-value">{{r.name}}：{{r.explanation}}</p><pre v-if="result.custom_admission">{{JSON.stringify(result.custom_admission,null,2)}}</pre></details><h4>同质量替换例外</h4><p>{{result.summary.comparison.some(r=>r.dimension==='special')?'质量相当时，可将特效字幕依据由 PGS 推定更新为发布者明确标注；最终文件关联仍须确认。':'当前策略不适用特效字幕的同质量替换例外。'}}</p><p v-if="schedule">观察{{schedule.observation_enabled?'已启用':'未启用'}} · 冷却{{schedule.cooldown_enabled?'已启用':'未启用'}} · {{schedule.supersession_limit===0?'禁止自动取代':'最多取代 '+schedule.supersession_limit+' 次'}}</p><p v-if="schedule?.observation_enabled&&[schedule.base_seconds,schedule.quiet_seconds,schedule.max_seconds].some(v=>v==null)" role="alert">观察已启用，但时间参数不完整，请在等待与更换版本设置中补齐。</p><small>以上为当前草稿，不会执行搜索或下载。</small></details></template></section></template>
